好的，这是一个**完全不依赖任何库（不用 Three.js）的纯 HTML/CSS/纯 JS 3D 待办列表**：

- 可拖拽旋转视角
- 点击卡片切换“待完成 / 已完成”
- 点右上角 × 删除任务
- 底部输入框可以添加新任务

```html
<!DOCTYPE html>
<html lang="zh">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>纯 CSS 3D 待办列表</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            min-height: 100vh;
            overflow: hidden;
            font-family: "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
            color: #fff;
        }

        .viewport {
            position: fixed;
            inset: 0;
            display: flex;
            align-items: center;
            justify-content: center;
            perspective: 1600px;
            background: radial-gradient(circle at 50% 60%, #1b2945 0%, #0a0e17 80%);
        }

        .carousel {
            position: relative;
            width: 0;
            height: 0;
            transform-style: preserve-3d;
        }

        /* 每张任务卡 */
        .todo-card {
            position: absolute;
            left: -120px;
            top: -80px;
            width: 240px;
            height: 160px;
            border-radius: 18px;
            padding: 18px 20px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            cursor: pointer;
            backface-visibility: hidden;
            -webkit-backface-visibility: hidden;
            box-shadow: 0 20px 35px rgba(0, 0, 0, 0.45);
            transition: transform 0.15s ease, box-shadow 0.2s ease;
            user-select: none;
            border: 1px solid rgba(255, 255, 255, 0.25);
        }

        .todo-card:hover {
            filter: brightness(1.15);
        }

        .todo-card .text {
            font-size: 16px;
            font-weight: 600;
            line-height: 1.4;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
            word-break: break-word;
            padding-right: 20px;
        }

        .todo-card .meta {
            font-size: 12px;
            opacity: 0.85;
            letter-spacing: 1px;
        }

        .del {
            position: absolute;
            top: 8px;
            right: 14px;
            background: none;
            border: none;
            color: #fff;
            font-size: 22px;
            line-height: 1;
            cursor: pointer;
            opacity: 0.55;
            padding: 4px;
            transition: opacity 0.2s;
        }

        .del:hover {
            opacity: 1;
        }

        /* 待办 */
        .pending {
            background: linear-gradient(145deg, rgba(255, 77, 77, 0.95), rgba(168, 30, 50, 0.95));
        }

        /* 已完成 */
        .done {
            background: linear-gradient(145deg, rgba(0, 200, 125, 0.95), rgba(10, 130, 85, 0.95));
        }

        /* 顶部提示 */
        .hint {
            position: fixed;
            top: 18px;
            left: 50%;
            transform: translateX(-50%);
            background: rgba(0, 0, 0, 0.4);
            border: 1px solid rgba(255, 255, 255, 0.1);
            padding: 8px 20px;
            border-radius: 40px;
            font-size: 13px;
            color: rgba(255, 255, 255, 0.9);
            backdrop-filter: blur(10px);
            z-index: 10;
            white-space: nowrap;
        }

        /* 底部添加栏 */
        .addbar {
            position: fixed;
            bottom: 22px;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            gap: 10px;
            align-items: center;
            background: rgba(255, 255, 255, 0.08);
            border: 1px solid rgba(255, 255, 255, 0.15);
            padding: 6px 8px 6px 16px;
            border-radius: 50px;
            backdrop-filter: blur(12px);
            z-index: 10;
        }

        .addbar input {
            background: transparent;
            border: none;
            outline: none;
            color: #fff;
            width: 220px;
            font-size: 14px;
            padding: 6px 4px;
        }

        .addbar input::placeholder {
            color: rgba(255, 255, 255, 0.5);
        }

        .addbar button {
            border: none;
            background: #3b82f6;
            color: #fff;
            padding: 8px 18px;
            border-radius: 40px;
            font-size: 14px;
            cursor: pointer;
            transition: background 0.2s;
        }

        .addbar button:hover {
            background: #2563eb;
        }
    </style>
</head>
<body>

    <div class="viewport">
        <div class="carousel" id="carousel"></div>
    </div>

    <div class="hint">🖱 拖动旋转 · 点击卡片切换状态 · 点 × 删除</div>

    <div class="addbar">
        <input type="text" id="taskInput" placeholder="添加新任务..." maxlength="20">
        <button id="addBtn">添加</button>
    </div>

    <script>
        // ============ 任务数据 ============
        const todos = [
            { text: '学习纯 CSS 3D 变换', done: false },
            { text: '写一个 TodoList', done: true },
            { text: '整理电脑桌面', done: false },
            { text: '完成本周周报', done: false },
            { text: '读 20 页书', done: false }
        ];

        // ============ 基础变量 ============
        let angle = 0;
        let drag = false;
        let moved = false;
        let startX = 0;
        let startAngle = 0;

        const viewport = document.querySelector('.viewport');
        const carousel = document.getElementById('carousel');
        const taskInput = document.getElementById('taskInput');
        const addBtn = document.getElementById('addBtn');

        function setGroupAngle() {
            carousel.style.transform = `rotateX(-10deg) rotateY(${angle}deg)`;
        }

        // ============ 渲染 3D 卡片环 ============
        function render() {
            carousel.innerHTML = '';

            const total = todos.length;
            if (total === 0) return;

            const radius = Math.min(520, Math.max(280, 160 + total * 35));
            const perAngle = 360 / total;

            todos.forEach((todo, index) => {
                const card = document.createElement('div');
                card.className = 'todo-card ' + (todo.done ? 'done' : 'pending');
                card.style.transform = `rotateY(${index * perAngle}deg) translateZ(${radius}px)`;

                // 任务文字
                const text = document.createElement('span');
                text.className = 'text';
                text.textContent = todo.text;

                // 状态文字
                const meta = document.createElement('span');
                meta.className = 'meta';
                meta.textContent = todo.done ? '✔ 已完成' : '○ 待完成';

                // 删除按钮
                const del = document.createElement('button');
                del.className = 'del';
                del.textContent = '×';

                del.addEventListener('click', (e) => {
                    e.stopPropagation();
                    if (moved) return;
                    todos.splice(index, 1);
                    render();
                });

                // 点击切换完成状态
                card.addEventListener('click', () => {
                    if (moved) return;

                    todo.done = !todo.done;
                    card.classList.toggle('done', todo.done);
                    card.classList.toggle('pending', !todo.done);
                    meta.textContent = todo.done ? '✔ 已完成' : '○ 待完成';
                });

                card.append(del, text, meta);
                carousel.appendChild(card);
            });
        }

        // ============ 鼠标拖拽旋转 ============
        viewport.addEventListener('pointerdown', (e) => {
            drag = true;
            moved = false;
            startX = e.clientX;
            startAngle = angle;
        });

        window.addEventListener('pointermove', (e) => {
            if (!drag) return;

            const dx = e.clientX - startX;
            if (Math.abs(dx) > 4) moved = true;

            angle = startAngle + dx * 0.35;
            setGroupAngle();
        });

        window.addEventListener('pointerup', () => {
            drag = false;
        });

        // ============ 添加任务 ============
        function addTask() {
            const text = taskInput.value.trim();
            if (!text) return;

            todos.push({
                text: text,
                done: false
            });

            render();
            taskInput.value = '';
            taskInput.focus();
        }

        addBtn.addEventListener('click', addTask);
        taskInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') addTask();
        });

        // ============ 初始化 ============
        render();
        setGroupAngle();
    </script>
</body>
</html>
```

直接复制保存为 `.html` 文件，用浏览器打开即可使用。

