      questGiven: false,
      quest: {
        id: 'q_it',
        type: 'talk',
        targetNpc: 'it',
        required: 1,
        title: '去找 IT 帮忙',
        desc: '小林说她的电脑坏了，请去找 IT 小哥告知一声',
        startText: '我的电脑又蓝屏啦……能帮我去找 IT 小哥说说吗？'
      }
    },
    {
      id: 'it',
      name: 'IT小哥',
      emoji: '🧑‍💻',
      x: 650, y: 460,
      questGiven: false,
      quest: {
        id: 'q_box',
        type: 'collect',
        itemType: 'package',
        required: 2,
        title: '搬 2 个服务器箱子',
        desc: '在角落找到2个黄色搬运箱，帮 IT 搬到机柜旁',
        startText: '这两个箱子要搬到机柜那边，帮忙拿一下。'
      }
    }
  ];

  // 地上的可收集物（文件 / 箱子）
  let pickups = [
    { type: 'paper',   x: 140, y: 340 },
    { type: 'paper',   x: 280, y: 430 },
    { type: 'paper',   x: 470, y: 490 },
    { type: 'paper',   x: 650, y: 230 },
    { type: 'paper',   x: 820, y: 470 },
    { type: 'package', x: 760, y: 160 },
    { type: 'package', x: 520, y: 600 }
  ];

  // 玩家当前任务列表
  let activeTasks = [];
  let questLogOpen = false;

  const dialogueEl = document.getElementById('dialogue');
  const questLogEl = document.getElementById('questLog');
  const questListEl = document.getElementById('questList');
  let dialogueTimer = null;

  function showDialogue(text, duration = 4500) {
    dialogueEl.innerHTML = text;
    dialogueEl.classList.add('show');
    clearTimeout(dialogueTimer);
    dialogueTimer = setTimeout(() => dialogueEl.classList.remove('show'), duration);
  }

  function openQuestLog() {
    questLogOpen = true;
    questLogEl.classList.add('open');
    renderQuestLog();
  }
  function closeQuestLog() {
    questLogOpen = false;
    questLogEl.classList.remove('open');
  }
  function toggleQuestLog() {
    if (questLogOpen) closeQuestLog();
    else openQuestLog();
  }

  function renderQuestLog() {
    if (!questLogOpen) return;
    if (activeTasks.length === 0) {
      questListEl.innerHTML = '<div style="color:#64748b;font-size:13px;padding:8px">还没有任务，去和同事们聊聊吧 🤝</div>';
      return;
    }
    let html = '';
    activeTasks.forEach(t => {
      const progress = t.type === 'collect'
        ? Math.min(t.progress, t.required) + ' / ' + t.required
        : (t.done ? '✅' : '❌');
      html += `
        <div class="qitem${t.done ? ' done' : ''}">
          <div class="title">${t.done ? '✅' : '📌'} ${t.title}</div>
          <div class="desc">${t.desc}</div>
          <div class="progress">完成度：${progress}</div>
        </div>`;
    });
    questListEl.innerHTML = html;
  }

  // 从 NPC 处接任务
  function startQuestFromNPC(npc) {
    if (!npc.quest || npc.questGiven) return null;
    const q = npc.quest;
    activeTasks.push({
      id: q.id,
      type: q.type,
      itemType: q.itemType || null,
      targetNpc: q.targetNpc || null,
      required: q.required,
      title: q.title,
      desc: q.desc,
      progress: 0,
      done: false
    });
    npc.questGiven = true;
    renderQuestLog();
    return npc.name + '：' + q.startText + '<br><b style="color:#ffd76a">【新任务：' + q.title + '】</b>';
  }

  // 完成“传话”类任务
  function completeTalkQuest(npcId) {
    let completedTitle = null;
    activeTasks.forEach(t => {
      if (!t.done && t.type === 'talk' && t.targetNpc === npcId) {
        t.done = true;
        t.progress = 1;
        completedTitle = t.title;
      }
    });
    if (completedTitle) {
      renderQuestLog();
      return '<b style="color:#58d68d">✅ 任务完成：' + completedTitle + '</b>';
    }
    return null;
  }

  // 拾取物品，判断有无对应收集任务
  function pickupItem(pickupIndex) {
    const p = pickups[pickupIndex];
    let got = false;
    let finishedTitle = '';
    activeTasks.forEach(t => {
      if (!t.done && t.type === 'collect' && t.itemType === p.type) {
        t.progress++;
        got = true;
        if (t.progress >= t.required) {
          t.done = true;
          finishedTitle = t.title;
        }
      }
    });

    if (got) {
      pickups.splice(pickupIndex, 1);
      renderQuestLog();
      if (finishedTitle) {
        showDialogue('<b style="color:#58d68d">✅ 任务完成：' + finishedTitle + '</b>', 3500);
      } else {
        showDialogue(p.type === 'paper' ? '收集到文件 📄' : '收集到服务器箱子 📦', 1200);
      }
    }
    // 没有对应任务时不消失，避免任务永远无法完成
  }

  // 与 NPC 互动
  function contactNPC(npc) {
    const messages = [];
    const npcQuestMsg = startQuestFromNPC(npc);
    if (npcQuestMsg) messages.push(npcQuestMsg);

    const talkCompleteMsg = completeTalkQuest(npc.id);
    if (talkCompleteMsg) messages.push(talkCompleteMsg);

    if (messages.length > 0) {
      showDialogue(messages.join('<br>'), 5000);
    } else if (npc.questGiven) {
      // 已接任务但仍可聊两句
      showDialogue(npc.name + '：加油！我还指望你完成任务呢。', 2000);
    }
  }

  // --- 键盘移动 ---
  const keys = {};
  document.addEventListener('keydown', e => {
    const k = e.key.toLowerCase();
    keys[k] = true;
    if (k === 'q') toggleQuestLog();
    if (['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)) e.preventDefault();
  });
  document.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });

  // --- 碰撞检测 ---
  function circleRectCollision(cx, cy, r, rect) {
    const nx = Math.max(rect.x, Math.min(cx, rect.x + rect.w));
    const ny = Math.max(rect.y, Math.min(cy, rect.y + rect.h));
    return (cx - nx) ** 2 + (cy - ny) ** 2 < r * r;
  }

  function canMoveTo(x, y) {
    if (x < 22 || x > W - 22 || y < 22 || y > H - 22) return false;
    for (const o of obstacles) {
      if (circleRectCollision(x, y, player.r - 3, o)) return false;
    }
    return true;
  }

  function update() {
    if (questLogOpen) return;  // 打开任务日志时人物暂不移动

    let dx = 0, dy = 0;
    if (keys['arrowleft'] || keys['a']) dx -= 1;
    if (keys['arrowright'] || keys['d']) dx += 1;
    if (keys['arrowup'] || keys['w']) dy -= 1;
    if (keys['arrowdown'] || keys['s']) dy += 1;

    if (dx || dy) {
      const len = Math.hypot(dx, dy);
      dx = dx / len * 3;
      dy = dy / len * 3;
      if (canMoveTo(player.x + dx, player.y)) player.x += dx;
      if (canMoveTo(player.x, player.y + dy)) player.y += dy;
    }

    // 捡物品
    for (let i = pickups.length - 1; i >= 0; i--) {
      const p = pickups[i];
      if (Math.hypot(p.x - player.x, p.y - player.y) < 28) {
        pickupItem(i);
      }
    }

    // 碰 NPC
    for (const npc of npcs) {
      if (Math.hypot(npc.x - player.x, npc.y - player.y) < 55) {
        contactNPC(npc);
      }
    }
  }

  // --- 双击自己打开任务日志 ---
  canvas.addEventListener('dblclick', e => {
    const rect = canvas.getBoundingClientRect();
    const sx = (e.clientX - rect.left) * (W / rect.width);
    const sy = (e.clientY - rect.top) * (H / rect.height);
    if (Math.hypot(sx - player.x, sy - player.y) < 45) {
      toggleQuestLog();
    }
  });

  document.getElementById('closeLog').addEventListener('click', closeQuestLog);

  // --- 绘制 ---
  function draw() {
    ctx.clearRect(0, 0, W, H);

    // 地毯底色
    ctx.fillStyle = '#b8c0c9';
    ctx.fillRect(0, 0, W, H);

    // 地板纹理
    ctx.strokeStyle = 'rgba(255,255,255,0.15)';
    ctx.lineWidth = 1;
    for (let i = 0; i < W; i += 40) {
      ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, H); ctx.stroke();
    }
    for (let i = 0; i < H; i += 40) {
      ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(W, i); ctx.stroke();
    }

    // 中央活动区
    ctx.fillStyle = 'rgba(230,220,205,0.4)';
    ctx.fillRect(30, 30, W - 60, H - 60);

    // 办公室里的家具
    drawObstacles();

    // 收集物
    drawPickups();

    // NPC
    npcs.forEach(drawNPC);

    // 玩家
    drawPlayer();
  }

  function drawObstacles() {
    obstacles.forEach(o => {
      const { x, y, w, h, type } = o;

      // 底部阴影
      ctx.fillStyle = 'rgba(0,0,0,0.12)';
      roundRect(x + 4, y + 4, w, h, 5);

      // 主体颜色
      if (type === 'desk') ctx.fillStyle = '#b8915e';
      else if (type === 'table') ctx.fillStyle = '#cbc2b0';
      else if (type === 'cabinet') ctx.fillStyle = '#7d8a99';
      else if (type === 'server') ctx.fillStyle = '#4d5a69';
      else if (type === 'plants') ctx.fillStyle = '#5b8c4e';
      else if (type === 'water') ctx.fillStyle = '#91b3c7';
      else ctx.fillStyle = '#aaaaaa';
      roundRect(x, y, w, h, 6);

      // 简单纹理
      ctx.fillStyle = 'rgba(255,255,255,0.18)';
      roundRect(x + w/2 - w*0.2, y + h/2 - h*0.25, w*0.4, h*0.15, 3);

      if (type === 'plants') {
        // 绿植叶子
        ctx.fillStyle = '#4e8b45';
        ctx.beginPath();
        ctx.arc(x + w/2, y - 3, 18, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#6cad60';
        ctx.beginPath();
        ctx.arc(x + w/2 - 7, y - 7, 12, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(x + w/2 + 9, y - 5, 10, 0, Math.PI * 2);
        ctx.fill();
      }
    });
  }

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.fill();
  }

  function drawPickups() {
    pickups.forEach(p => {
      // 阴影
      ctx.fillStyle = 'rgba(0,0,0,0.12)';
      ctx.beginPath();
      ctx.ellipse(p.x + 2, p.y + 8, 14, 4, 0, 0, Math.PI * 2);
      ctx.fill();

      if (p.type === 'paper') {
        // 白色 A4 纸
        ctx.fillStyle = '#fdfdfd';
        roundRect(p.x - 12, p.y - 9, 20, 28, 3);
        ctx.fillStyle = '#d3d3d3';
        ctx.fillRect(p.x - 5, p.y - 3, 10, 4);
        ctx.fillRect(p.x - 5, p.y + 5, 10, 4);
        ctx.fillRect(p.x - 5, p.y + 13, 10, 4);
        ctx.fillStyle = '#5580ff';
        ctx.beginPath();
        ctx.arc(p.x - 7, p.y - 3, 3, 0, Math.PI * 2);
        ctx.fill();
      } else if (p.type === 'package') {
        // 黄色包装箱
        ctx.fillStyle = '#e2b23a';
        ctx.fillRect(p.x - 14, p.y - 8, 28, 22);
        ctx.strokeStyle = '#b17a1b';
        ctx.lineWidth = 2;
        ctx.strokeRect(p.x - 14, p.y - 8, 28, 22);
        ctx.beginPath();
        ctx.moveTo(p.x - 14, p.y - 8);
        ctx.lineTo(p.x + 14, p.y + 14);
        ctx.moveTo(p.x + 14, p.y - 8);
        ctx.lineTo(p.x - 14, p.y + 14);
        ctx.strokeStyle = 'rgba(177,122,27,0.7)';
        ctx.stroke();
        ctx.font = 'bold 9px sans-serif';
        ctx.fillStyle = '#7a4d00';
        ctx.textAlign = 'center';
        ctx.fillText('SERVER', p.x, p.y - 14);
      }
    });
  }

  function drawNPC(npc) {
    // 影子
    ctx.fillStyle = 'rgba(0,0,0,0.18)';
    ctx.beginPath();
    ctx.ellipse(npc.x + 2, npc.y + 12, 16, 4, 0, 0, Math.PI * 2);
    ctx.fill();

    // 角色
    ctx.font = '34px "Segoe UI Emoji", "Noto Color Emoji", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(npc.emoji, npc.x, npc.y);

    // 名字
    ctx.font = 'bold 13px "Segoe UI", Arial, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.lineWidth = 3;
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.strokeText(npc.name, npc.x, npc.y - 24);
    ctx.fillStyle = '#fff';
    ctx.fillText(npc.name, npc.x, npc.y - 24);

    if (!npc.questGiven && npc.quest) {
      ctx.font = 'bold 18px sans-serif';
      ctx.fillStyle = '#ffd75e';
      ctx.strokeStyle = '#7a5c00';
      ctx.lineWidth = 2;
      ctx.strokeText('!', npc.x + 22, npc.y - 18);
      ctx.fillText('!', npc.x + 22, npc.y - 18);
    }
  }

  function drawPlayer() {
    // 影子
    ctx.fillStyle = 'rgba(0,0,0,0.22)';
    ctx.beginPath();
    ctx.ellipse(player.x + 2, player.y + 9, 18, 5, 0, 0, Math.PI * 2);
    ctx.fill();

    // 选中光圈
    ctx.strokeStyle = 'rgba(255,240,160,0.5)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(player.x, player.y + 1, 20, 18, 0, 0, Math.PI * 2);
    ctx.stroke();

    ctx.font = '34px "Segoe UI Emoji", "Noto Color Emoji", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(player.emoji, player.x, player.y);
  }

  // --- 游戏主循环 ---
  let lastTime = 0;
  function gameLoop(time) {
    update();
    draw();
    requestAnimationFrame(gameLoop);
  }
  requestAnimationFrame(gameLoop);

})();
</script>
</body>
</html>
```

你把这个文件保存成 `.html`，在浏览器里打开就可以玩了。  
办公室里走一走，找老板、小林、IT 小哥接任务，地面上可以捡到文件和箱子，完成任务后任务栏里会打勾 ✅。

