</div>

<script>
(function () {
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;

  // --- 玩家 ---
  const player = {
    x: 300, y: 300, r: 18, speed: 3.2, emoji: '🧙'
  };

  // --- 地图装饰：树（不可通过） ---
  const trees = [
    { x: 90,  y: 80,  r: 28 },
    { x: 120, y: 530, r: 28 },
    { x: 710, y: 90,  r: 28 },
    { x: 780, y: 520, r: 28 },
    { x: 450, y: 85,  r: 26 },
    { x: 820, y: 250, r: 26 }
  ];

  // --- NPC ---
  const npcs = [
    {
      id: 'old',
      name: '老王',
      emoji: '👴',
      x: 240, y: 180,
      questGiven: false,
      quest: {
        id: 'q_flower',
        title: '采集3朵花',
        desc: '在草地上采集3朵花',
        type: 'collect',
        itemType: 'flower',
        required: 3,
        startText: '老伴喜欢花…你能帮我采3朵吗？'
      }
    },
    {
      id: 'mei',
      name: '小美',
      emoji: '👩',
      x: 680, y: 170,
      questGiven: false,
      quest: {
        id: 'q_talk',
        title: '传话给铁匠',
        desc: '和小美对话后，去找铁匠告诉他',
        type: 'talk',
        targetNpc: 'blacksmith',
        required: 1,
        startText: '可以帮我把消息带给铁匠吗？'
      }
    },
    {
      id: 'blacksmith',
      name: '铁匠',
      emoji: '🧔',
      x: 560, y: 440,
      questGiven: false,
      quest: {
        id: 'q_stone',
        title: '收集2块石头',
        desc: '在地上找到2块石头',
        type: 'collect',
        itemType: 'stone',
        required: 2,
        startText: '我需要石头打铁，帮我找2块。'
      }
    }
  ];

  // --- 地上的收集物 ---
  let pickups = [
    { type: 'flower', x: 260, y: 400 },
    { type: 'flower', x: 360, y: 490 },
    { type: 'flower', x: 520, y: 280 },
    { type: 'flower', x: 690, y: 330 },
    { type: 'flower', x: 130, y: 390 },

    { type: 'stone', x: 480, y: 140 },
    { type: 'stone', x: 230, y: 240 },
    { type: 'stone', x: 760, y: 380 },
    { type: 'stone', x: 320, y: 550 }
  ];

  // --- 任务状态 ---
  let activeTasks = [];
  let questLogOpen = false;

  // --- UI helpers ---
  const dialogueEl = document.getElementById('dialogue');
  const questLogEl = document.getElementById('questLog');
  const questListEl = document.getElementById('questList');
  let dialogueTimer = null;

  function showDialogue(text, duration = 4000) {
    dialogueEl.innerHTML = text;
    dialogueEl.classList.add('show');
    clearTimeout(dialogueTimer);
    dialogueTimer = setTimeout(() => dialogueEl.classList.remove('show'), duration);
  }

  function keyLabel(text) {
    return '<span style="background:#333;padding:2px 6px;border-radius:4px;color:#ddd">' + text + '</span>';
  }

  function openQuestLog() {
    questLogOpen = true;
    questLogEl.classList.add('open');
    renderQuestLog();
  }

  function closeQuestLog() {
    questLogOpen = false;
    questLogEl.classList.remove('open');
  }

  function toggleQuestLog() {
    if (questLogOpen) closeQuestLog();
    else openQuestLog();
  }

  function renderQuestLog() {
    if (!questLogOpen) return;
    if (activeTasks.length === 0) {
      questListEl.innerHTML = '<div style="color:#64748b;font-size:13px;padding:8px">还没有任务，去碰碰村里的NPC吧 👀</div>';
      return;
    }
    let html = '';
    activeTasks.forEach((t) => {
      const progressText = t.type === 'collect'
        ? (Math.min(t.progress, t.required) + ' / ' + t.required)
        : (t.done ? ' ✅' : ' ❌');
      html += `
        <div class="qitem${t.done ? ' done' : ''}">
          <div class="title">${t.done ? '✅' : '📋'} ${t.title}</div>
          <div class="desc">${t.desc}</div>
          <div class="progress">进度：${progressText}</div>
        </div>
      `;
    });
    questListEl.innerHTML = html;
  }

  // --- 任务逻辑 ---
  function startQuestFromNPC(npc) {
    if (npc.questGiven || !npc.quest) return null;
    const q = npc.quest;
    activeTasks.push({
      id: q.id,
      type: q.type,
      title: q.title,
      desc: q.desc,
      itemType: q.itemType || null,
      targetNpc: q.targetNpc || null,
      required: q.required,
      progress: 0,
      done: false
    });
    npc.questGiven = true;
    return npc.name + '：' + q.startText + ' …… <b style="color:#ffd76a">【获得任务：' + q.title + '】</b>';
  }

  function completeTalkQuest(npcId) {
    let completed = false;
    let title = '';
    activeTasks.forEach((t) => {
      if (t.type === 'talk' && t.targetNpc === npcId && !t.done) {
        t.progress = 1;
        t.done = true;
        completed = true;
        title = t.title;
      }
    });
    return completed ? '<b style="color:#58d68d">✅ 任务完成：' + title + '</b>' : null;
  }

  function collectPickup(p) {
    let matched = false;
    let finishedTitle = '';

    for (let t of activeTasks) {
      if (t.type === 'collect' && !t.done && t.itemType === p.type) {
        t.progress++;
        matched = true;
        if (t.progress >= t.required) {
          t.done = true;
          finishedTitle = t.title;
        }
      }
    }

    if (matched) {
      pickups.splice(pickups.indexOf(p), 1);
      renderQuestLog();
      if (finishedTitle) {
        showDialogue('<b style="color:#58d68d">✅ 任务完成：' + finishedTitle + '</b>', 3500);
      } else {
        showDialogue('获得：' + (p.type === 'flower' ? '🌸花朵' : '🪨石头'), 1200);
      }
    }
    // 没有相关任务时东西不会消失，避免任务永远完成不了
  }

  // --- 碰到 / 互动NPC ---
  function npcContact(npc) {
    const messages = [];

    // 领取NPC自己的任务
    const questMsg = startQuestFromNPC(npc);
    if (questMsg) messages.push(questMsg);

    // 完成“传话/交谈”类任务
    const talkMsg = completeTalkQuest(npc.id);
    if (talkMsg) messages.push(talkMsg);

    if (messages.length > 0) {
      showDialogue(messages.join('　'), 5000);
      renderQuestLog();
    }
  }

  // --- 键盘/移动 ---
  const keys = {};
  document.addEventListener('keydown', (e) => {
    const k = e.key.toLowerCase();
    keys[k] = true;
    if (k === 'q') toggleQuestLog();
    if (['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)) e.preventDefault();
  });
  document.addEventListener('keyup', (e) => {
    keys[e.key.toLowerCase()] = false;
  });

  function collideTreeTest(x, y, r) {
    for (const t of trees) {
      const dist = Math.hypot(t.x - x, t.y - y);
      if (dist < t.r + r) return true;
    }
    return false;
  }

  function canMoveTo(x, y) {
    if (x < 20 || x > W - 20 || y < 20 || y > H - 20) return false;
    if (collideTreeTest(x, y, player.r - 4)) return false;
    return true;
  }

  // --- 双击自己查看任务 ---
  canvas.addEventListener('dblclick', (e) => {
    const rect = canvas.getBoundingClientRect();
    const sx = (e.clientX - rect.left) * (W / rect.width);
    const sy = (e.clientY - rect.top) * (H / rect.height);
    const dist = Math.hypot(sx - player.x, sy - player.y);
    if (dist < 48) {
      toggleQuestLog();
    }
  });

  // 关闭按钮
  document.getElementById('closeLog').addEventListener('click', closeQuestLog);

  // --- 更新 ---
  function update() {
    if (questLogOpen) return;

    let dx = 0, dy = 0;
    if (keys['arrowleft'] || keys['a']) dx -= 1;
    if (keys['arrowright'] || keys['d']) dx += 1;
    if (keys['arrowup'] || keys['w']) dy -= 1;
    if (keys['arrowdown'] || keys['s']) dy += 1;

    if (dx !== 0 || dy !== 0) {
      const len = Math.hypot(dx, dy);
      dx = dx / len * player.speed;
      dy = dy / len * player.speed;

      // 轴分离碰撞
      if (canMoveTo(player.x + dx, player.y)) player.x += dx;
      if (canMoveTo(player.x, player.y + dy)) player.y += dy;
    }

    // 采集地上的花 / 石头
    for (const p of pickups) {
      if (Math.hypot(p.x - player.x, p.y - player.y) < 26) {
        collectPickup(p);
      }
    }

    // 碰到NPC
    for (const npc of npcs) {
      if (Math.hypot(npc.x - player.x, npc.y - player.y) < 55) {
        npcContact(npc);
      }
    }
  }

  // --- 绘制 ---
  function draw() {
    ctx.clearRect(0, 0, W, H);

    // 草地
    ctx.fillStyle = '#7cb555';
    ctx.fillRect(0, 0, W, H);

    // 网格纹理
    ctx.strokeStyle = 'rgba(255,255,255,0.06)';
    ctx.lineWidth = 1;
    for (let i = 0; i < W; i += 40) {
      ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, H); ctx.stroke();
    }
    for (let i = 0; i < H; i += 40) {
      ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(W, i); ctx.stroke();
    }

    // 小路
    ctx.fillStyle = 'rgba(194,158,96,0.25)';
    ctx.beginPath();
    ctx.moveTo(280, 190);
    ctx.lineTo(680, 170);
    ctx.lineTo(580, 450);
    ctx.lineTo(260, 430);
    ctx.closePath();
    ctx.fill();

    // 树
    drawTrees();

    // 地上的采集物
    drawPickups();

    // NPC
    npcs.forEach(drawNPC);

    // 玩家
    drawPlayer();
  }

  function drawTrees() {
    trees.forEach((t) => {
      ctx.fillStyle = 'rgba(0,0,0,0.18)';
      ctx.beginPath();
      ctx.ellipse(t.x + 3, t.y + t.r * 0.5, t.r * 0.8, 5, 0, 0, 2 * Math.PI);
      ctx.fill();

      // 树干
      ctx.fillStyle = '#6f4a2d';
      ctx.fillRect(t.x - 5, t.y - 4, 10, 16);

      // 树冠
      ctx.fillStyle = '#3d7a37';
      ctx.beginPath();
      ctx.arc(t.x, t.y - 10, t.r, 0, 2 * Math.PI);
      ctx.fill();

      ctx.fillStyle = '#4f9147';
      ctx.beginPath();
      ctx.arc(t.x - 6, t.y - 18, t.r * 0.7, 0, 2 * Math.PI);
      ctx.fill();

      ctx.fillStyle = '#5aa851';
      ctx.beginPath();
      ctx.arc(t.x + 7, t.y - 12, t.r * 0.7, 0, 2 * Math.PI);
      ctx.fill();
    });
  }

  function drawPickups() {
    pickups.forEach((p) => {
      ctx.fillStyle = 'rgba(0,0,0,0.15)';
      ctx.beginPath();
      ctx.ellipse(p.x + 2, p.y + 5, 10, 4, 0, 0, 2 * Math.PI);
      ctx.fill();

      if (p.type === 'flower') {
        // 花茎
        ctx.strokeStyle = '#2d7a2d';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x, p.y + 6);
        ctx.stroke();

        // 花瓣
        ctx.fillStyle = '#f16b9a';
        for (let i = 0; i < 5; i++) {
          const angle = (i * 2 * Math.PI) / 5;
          ctx.beginPath();
          ctx.arc(p.x + Math.cos(angle) * 6, p.y + Math.sin(angle) * 6, 4, 0, 2 * Math.PI);
          ctx.fill();
        }
        // 花心
        ctx.fillStyle = '#ffd942';
        ctx.beginPath();
        ctx.arc(p.x, p.y, 4, 0, 2 * Math.PI);
        ctx.fill();
      } else {
        // 石头
        ctx.fillStyle = '#8b8b90';
        ctx.beginPath();
        ctx.ellipse(p.x, p.y, 8, 6, 0.4, 0, 2 * Math.PI);
        ctx.fill();
        ctx.fillStyle = '#afafb5';
        ctx.beginPath();
        ctx.ellipse(p.x - 2, p.y - 2, 3, 2, 0.4, 0, 2 * Math.PI);
        ctx.fill();
        ctx.fillStyle = '#5c5c62';
        ctx.beginPath();
        ctx.arc(p.x + 3, p.y + 4, 2, 0, 2 * Math.PI);
        ctx.fill();
      }
    });
  }

  function drawNPC(npc) {
    // 影子
    ctx.fillStyle = 'rgba(0,0,0,0.2)';
    ctx.beginPath();
    ctx.ellipse(npc.x + 2, npc.y + 10, 16, 5, 0, 0, 2 * Math.PI);
    ctx.fill();

    // emoji
    ctx.font = '36px "Segoe UI Emoji", "Noto Color Emoji", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(npc.emoji, npc.x, npc.y);

    // 名字
    ctx.font = 'bold 13px "Segoe UI", Arial, sans-serif';
    ctx.textBaseline = 'alphabetic';
    ctx.lineWidth = 3;
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.strokeText(npc.name, npc.x, npc.y - 30);
    ctx.fillStyle = '#ffffff';
    ctx.fillText(npc.name, npc.x, npc.y - 30);

    // 未领取任务标记
    if (!npc.questGiven && npc.quest) {
      ctx.font = 'bold 18px sans-serif';
      ctx.fillStyle = '#ffd75e';
      ctx.strokeStyle = '#7a5c00';
      ctx.lineWidth = 2;
      ctx.strokeText('!', npc.x + 22, npc.y - 22);
      ctx.fillText('!', npc.x + 22, npc.y - 22);
    }
  }

  function drawPlayer() {
    // 影子
    ctx.fillStyle = 'rgba(0,0,0,0.25)';
    ctx.beginPath();
    ctx.ellipse(player.x + 2, player.y + 8, 20, 6, 0, 0, 2 * Math.PI);
    ctx.fill();

    // 脚下光圈（方便识别位置）
    ctx.strokeStyle = 'rgba(255,255,120,0.2)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(player.x, player.y + 4, 18, 8, 0, 0, 2 * Math.PI);
    ctx.stroke();

    ctx.font = '38px "Segoe UI Emoji", "Noto Color Emoji", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(player.emoji, player.x, player.y);
  }

  // --- 主循环 ---
  let lastTime = 0;
  function gameLoop(time) {
    const dt = Math.min(time - lastTime, 50);
    lastTime = time;

    // 按时间限频移动速度
    const prevSpeed = player.speed;
    player.speed = prevSpeed; // 保持稳定（不改 = 按帧跑）

    update();
    draw();
    requestAnimationFrame(gameLoop);
  }

  requestAnimationFrame((t) => {
    lastTime = t;
    gameLoop(t);
  });

})();
</script>
</body>
</html>
```

明白了，我们来把这个场景做成一个可以直接在浏览器里看的 HTML 页面。

下面是一份**完整的自包含 HTML 代码**。你可以把它复制保存为 `.html` 文件，然后用浏览器打开，体验一个带古风界面的文字 RPG 场景。

