## 怎么使用

把上面的代码完整复制，保存为一个 `.html` 文件（比如 `jianghu.html` ），然后用任意浏览器双击打开，就能看到这个古风 RPG 场景页面。

页面底部有选择按钮，也可以自己输入行动。  
每次选择后，页面会显示你的想法——你只需要把选择的内容**回复给我**，我就继续推进剧情，并可以给你更新一版新的 HTML 页面。

现在，你选哪个？  
直接回复 **1、2、3、4** 或 **自定义行动** 都可以。

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Todo List</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: system-ui, -apple-system, sans-serif;
      background: linear-gradient(135deg, #667eea, #764ba2);
      min-height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
      padding: 20px;
    }
    .container {
      width: 100%;
      max-width: 500px;
      background: #fff;
      border-radius: 16px;
      padding: 30px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.2);
    }
    h1 {
      text-align: center;
      margin-bottom: 24px;
      color: #333;
      font-size: 32px;
      letter-spacing: 1px;
    }
    .input-section {
      display: flex;
      gap: 10px;
      margin-bottom: 20px;
    }
    #taskInput {
      flex: 1;
      padding: 12px 16px;
      font-size: 16px;
      border: 2px solid #e0e0e0;
      border-radius: 8px;
      outline: none;
      transition: border-color 0.3s;
    }
    #taskInput:focus {
      border-color: #667eea;
    }
    #addBtn {
      padding: 12px 20px;
      font-size: 16px;
      border: none;
      background: #667eea;
      color: #fff;
      border-radius: 8px;
      cursor: pointer;
      transition: background 0.3s;
      font-weight: 600;
    }
    #addBtn:hover {
      background: #5a6fd6;
    }
    ul {
      list-style: none;
    }
    li {
      display: flex;
      align-items: center;
      padding: 14px 12px;
      border-bottom: 1px solid #f0f0f0;
      transition: background 0.2s;
      border-radius: 8px;
    }
    li:last-child {
      border-bottom: none;
    }
    li:hover {
      background: #f9f9ff;
    }
    li input[type="checkbox"] {
      width: 20px;
      height: 20px;
      cursor: pointer;
      accent-color: #667eea;
      flex-shrink: 0;
    }
    .text {
      flex: 1;
      margin-left: 12px;
      font-size: 17px;
      color: #333;
      word-break: break-word;
      line-height: 1.4;
    }
    li.done .text {
      text-decoration: line-through;
      color: #aaa;
    }
    .delete-btn {
      background: none;
      border: none;
      font-size: 22px;
      cursor: pointer;
      color: #ff6b6b;
      padding: 0 6px;
      flex-shrink: 0;
      transition: transform 0.2s, color 0.2s;
      line-height: 1;
    }
    .delete-btn:hover {
      color: #e05050;
      transform: scale(1.2);
    }
  </style>
</head>
<body>
  <div class="container">
    <h1>📝 Todo List</h1>
    <div class="input-section">
      <input type="text" id="taskInput" placeholder="Add a new task..." autocomplete="off">
      <button id="addBtn">Add</button>
    </div>
    <ul id="taskList"></ul>
  </div>

  <script>
    const taskInput = document.getElementById('taskInput');
    const addBtn = document.getElementById('addBtn');
    const taskList = document.getElementById('taskList');

    let tasks = JSON.parse(localStorage.getItem('tasks')) || [];

    function save() {
      localStorage.setItem('tasks', JSON.stringify(tasks));
    }

    function render() {
      taskList.innerHTML = '';
      tasks.forEach((task, index) => {
        const li = document.createElement('li');
        if (task.done) li.classList.add('done');

        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = task.done;
        checkbox.dataset.index = index;

        const span = document.createElement('span');
        span.className = 'text';
        span.textContent = task.text;

        const deleteBtn = document.createElement('button');
        deleteBtn.className = 'delete-btn';
        deleteBtn.innerHTML = '&times;';
        deleteBtn.dataset.index = index;

        li.appendChild(checkbox);
        li.appendChild(span);
        li.appendChild(deleteBtn);

        taskList.appendChild(li);
      });
    }

    function addTask() {
      const text = taskInput.value.trim();
      if (text === '') return;
      tasks.push({ text, done: false });
      save();
      taskInput.value = '';
      render();
    }

    addBtn.addEventListener('click', addTask);

    taskInput.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') addTask();
    });

    taskList.addEventListener('click', (e) => {
      const target = e.target;
      if (target.classList.contains('delete-btn')) {
        const index = target.dataset.index;
        tasks.splice(index, 1);
        save();
        render();
      } else if (target.type === 'checkbox') {
        const index = target.dataset.index;
        tasks[index].done = target.checked;
        save();
        render();
      }
    });

    render();
  </script>
</body>
</html>
```

我理解为：做一个**能在浏览器里打开的“网页游戏版 Todo List”**，带等级、经验和完成动画，而不是纯文字清单。

把下面代码保存成一个 `.html` 文件（比如 `todo-game.html`），用浏览器打开就能玩：

```html
<!DOCTYPE html>
<html lang="zh">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>任务勇者 - 网页游戏版 TodoList</title>
<style>
  body {
    margin:0;
    background: #282c34;
    font-family: 'Segoe UI', Arial, sans-serif;
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
  }
  .container {
    background: #20232a;
    border-radius: 16px;
    padding: 24px;
    width: 400px;
    color: #61dafb;
    box-shadow: 0 8px 24px rgba(0,0,0,0.6);
  }
  h1 { margin: 0 0 16px; font-size: 28px; text-align:center; color:#e6a23c; }
  .stats {
    background: #171a1f;
    border-radius: 10px;
    padding: 12px;
    margin-bottom: 10px;
    display: flex;
    justify-content: space-between;
    font-weight:bold;
  }
  .exp-bar {
    background: #171a1f;
    border-radius: 8px;
    height: 12px;
    overflow: hidden;
    margin-bottom: 16px;
  }
  .exp-fill {
    height: 100%;
    width: 0%;
    background: linear-gradient(90deg, #e6a23c, #61dafb);
    transition: width 0.3s;
  }
  .add-box { display:flex; gap:8px; margin-bottom: 12px; }
  .add-box input {
    flex:1;
    padding: 10px;
    border: 1px solid #3d3d3d;
    background: #171a1f;
    border-radius: 6px;
    color:#fff;
    outline:none;
  }
  .add-box button {
    background:#e6a23c;
    border:none;
    border-radius:6px;
    padding:0 12px;
    font-size:18px;
    cursor:pointer;
  }
  .task-item {
    display:flex;
    align-items:center;
    background: #171a1f;
    padding: 8px 12px;
    border-radius: 8px;
    margin-bottom:6px;
  }
  .task-check {cursor:pointer; font-size:20px;}
  .task-name {flex:1; margin-left:8px; color:#fff;}
  .task-item.done .task-name {text-decoration: line-through; color:#888;}
  .task-del {background:none; border:none; cursor:pointer; color:#f56c6c; font-size:17px;}
</style>
</head>
<body>
<div class="container">
  <h1>🎮 任务勇者</h1>
  <div class="stats">
    <span>等级 <span id="level">1</span></span>
    <span>经验 <span id="expNow">0</span> / <span id="expMax">50</span></span>
  </div>
  <div class="exp-bar"><div id="expFill" class="exp-fill"></div></div>
  <div class="add-box">
    <input id="taskInput" placeholder="输入新任务">
    <button onclick="addTask()">➕</button>
  </div>
  <div id="list"></div>
  <div style="display:flex; justify-content:space-between; font-size:12px; margin-top:10px; color:#aaa;">
    <span>完成 <span id="doneCount">0</span>/<span id="totalCount">0</span></span>
    <button onclick="resetAll()" style="background:none;border:none;color:#61dafb;cursor:pointer;">重置冒险</button>
  </div>
</div>

<script>
  const input = document.getElementById('taskInput');
  const listEl = document.getElementById('list');
  const levelEl = document.getElementById('level');
  const expNowEl = document.getElementById('expNow');
  const expMaxEl = document.getElementById('expMax');
  const expFillEl = document.getElementById('expFill');
  const doneCountEl = document.getElementById('doneCount');
  const totalCountEl = document.getElementById('totalCount');

  const EXP_PER_TASK = 10;
  let tasks = [];
  let level = 1;
  let exp = 0;
  let expMax = 50;

  function updateExpMaxLabel() {
    expMaxEl.textContent = expMax;
  }

  function addExp(value) {
    exp += value;
    while (exp >= expMax) {
      exp -= expMax;
      level++;
      expMax = Math.floor(expMax * 1.5);
      alert('🎉 升级！当前等级 = ' + level);
    }
    updateExpMaxLabel();
    render();
  }

  function toggleTask(index) {
    const task = tasks[index];
    if (!task.done) {
      task.done = true;
      addExp(EXP_PER_TASK);
    } else {
      task.done = false;
      exp = Math.max(0, exp - EXP_PER_TASK);
      render();
    }
  }

  function deleteTask(index) {
    tasks.splice(index, 1);
    render();
  }

  function addTask() {
    const text = input.value.trim();
    if (!text) return;
    tasks.push({ name: text, done: false });
    input.value = '';
    render();
  }

  function taskHtml(item, index) {
    return `
      <div class="task-item ${item.done ? 'done' : ''}">
        <span class="task-check" onclick="toggleTask(${index})">${item.done ? '✅' : '⬜'}</span>
        <span class="task-name"></span>
        <button class="task-del" onclick="deleteTask(${index})">🗑️</button>
      </div>
    `;
  }

  function render() {
    levelEl.textContent = level;
    expNowEl.textContent = exp;
    updateExpMaxLabel();

    const percent = Math.min(100, (exp / expMax) * 100);
    expFillEl.style.width = percent + '%';

    listEl.innerHTML = tasks.map((t, idx) => taskHtml(t, idx)).join('');

    // 用 textContent 赋值，避免输入内容变成 HTML
    const nameEls = listEl.querySelectorAll('.task-name');
    tasks.forEach((t, idx) => {
      nameEls[idx].textContent = t.name;
    });

    doneCountEl.textContent = tasks.filter(t => t.done).length;
    totalCountEl.textContent = tasks.length;
  }

  function resetAll() {
    if (confirm('确定重置整个冒险吗？所有任务会清空。')) {
      tasks = [];
      level = 1;
      exp = 0;
      expMax = 50;
      render();
    }
  }

  input.addEventListener('keydown', e => {
    if (e.key === 'Enter') addTask();
  });

  render();
</script>
</body>
</html>
```

